const staticData = getWorkflowStaticData('global');

// Initialize processed URLs array if not exists
if (!staticData.processedUrls) {
  staticData.processedUrls = [];
}

// Get current article data
const currentUrl = items[0].json.link;
const articleTitle = items[0].json.title || 'Untitled';
const articlePubDate = items[0].json.pubDate || new Date().toISOString();
const rssContent = items[0].json.content || items[0].json.contentSnippet || '';
const rssSummary = items[0].json.contentSnippet || '';

// Check if URL was already processed
const isDuplicate = staticData.processedUrls.includes(currentUrl);

// Prepare output data
