// Multi-method web scraping with automatic fallback
const url = $input.first().json.articleUrl;
const rssContent = $input.first().json.rssContent;

let scrapedContent = '';
let scrapingMethod = 'None';

// Helper function to extract text from HTML
function extractTextFromHtml(html) {
  // Remove script and style tags
  let text = html.replace(/<script[^>]*>.*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>.*?<\/style>/gi, '');

  // Try to find article content using common selectors
  const articleMatches = text.match(/<article[^>]*>(.*?)<\/article>/is) ||
                        text.match(/<div[^>]*class="[^"]*content[^"]*"[^>]*>(.*?)<\/div>/is) ||
                        text.match(/<main[^>]*>(.*?)<\/main>/is);

  if (articleMatches && articleMatches[1]) {
    text = articleMatches[1];
  }

  // Remove remaining HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Clean up whitespace
  text = text.replace(/\s+/g, ' ').trim();

  return text;
}

// METHOD 1: Direct HTTP Request
try {
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      'Accept-Language': 'en-US,en;q=0.5'
    },
    redirect: 'follow'
  });

  if (response.ok) {
    const html = await response.text();
    scrapedContent = extractTextFromHtml(html);

    if (scrapedContent.length > 200) {
      scrapingMethod = 'HTTP Request';
      console.log('✅ HTTP Request succeeded');
    }
  }
} catch (error) {
  console.log('❌ HTTP Request failed:', error.message);
}

// METHOD 2: Apify (only if HTTP failed and API key is available)
if (!scrapedContent && $env.APIFY_API_TOKEN) {
  try {
    const apifyResponse = await fetch('https://api.apify.com/v2/acts/apify~web-scraper/run-sync-get-dataset-items', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${$env.APIFY_API_TOKEN}`
      },
      body: JSON.stringify({
        startUrls: [{ url: url }],
        pageFunction: 'async function pageFunction(context) { return { content: document.body.innerText }; }'
      })
    });

    if (apifyResponse.ok) {
      const data = await apifyResponse.json();
      if (data && data[0] && data[0].content) {
        scrapedContent = data[0].content;
        scrapingMethod = 'Apify';
        console.log('✅ Apify succeeded');
      }
    }
  } catch (error) {
    console.log('❌ Apify failed:', error.message);
  }
}

// METHOD 3: Firecrawl (only if previous methods failed and API key is available)
if (!scrapedContent && $env.FIRECRAWL_API_KEY) {
  try {
    const firecrawlResponse = await fetch('https://api.firecrawl.dev/v0/scrape', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${$env.FIRECRAWL_API_KEY}`
      },
      body: JSON.stringify({
        url: url,
        formats: ['markdown']
      })
    });

    if (firecrawlResponse.ok) {
      const data = await firecrawlResponse.json();
      if (data && data.data && data.data.markdown) {
        scrapedContent = data.data.markdown;
        scrapingMethod = 'Firecrawl';
        console.log('✅ Firecrawl succeeded');
      }
    }
  } catch (error) {
    console.log('❌ Firecrawl failed:', error.message);
  }
}

// FALLBACK: Use RSS content
if (!scrapedContent) {
  scrapedContent = rssContent || 'No content available';
  scrapingMethod = 'RSS Fallback';
  console.log('ℹ️ Using RSS content as fallback');
}

// Return the scraped content with metadata
return [{
  json: {
    ...$input.first().json,
    fullArticleContent: scrapedContent,
    scrapingMethod: scrapingMethod,
    contentLength: scrapedContent.length
  }
}];

