// Update static data with processed URL
const staticData = getWorkflowStaticData('global');

// Initialize array if needed
if (!staticData.processedUrls) {
  staticData.processedUrls = [];
}

// Add current URL to processed list
const currentUrl = items[0].json.URL;
if (!staticData.processedUrls.includes(currentUrl)) {
  staticData.processedUrls.push(currentUrl);

  // Keep only last 1000 URLs to prevent unlimited growth
  if (staticData.processedUrls.length > 1000) {
    staticData.processedUrls = staticData.processedUrls.slice(-1000);
  }
}

return items;
